#!/bin/bash
# Idempotent new-Mac setup. Generated by the mac-setup plugin; safe to re-run.
# Usage: bash bootstrap.sh [--dry-run]   (dry run prints actions, changes nothing)
set -u
DIR="$(cd "$(dirname "$0")" && pwd)"
DRY=0; [ "${1:-}" = "--dry-run" ] && DRY=1
run() { if [ "$DRY" = 1 ]; then echo "[dry-run] $*"; else "$@"; fi; }

if ! command -v brew >/dev/null && [ ! -x /opt/homebrew/bin/brew ] && [ ! -x /usr/local/bin/brew ]; then
  run /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"
fi
[ "$DRY" = 1 ] || eval "$(/opt/homebrew/bin/brew shellenv 2>/dev/null || /usr/local/bin/brew shellenv)"
echo "Note: some casks (Zoom, Docker, Logi) prompt for your password; stay at the terminal."

echo "==> Brewfile (App Store apps need you signed in to the App Store first)"
run brew bundle --no-upgrade --file="$DIR/Brewfile" || echo "Some Brewfile entries failed; re-run after fixing."

if [ -f "$DIR/Brewfile.extras" ]; then
  run brew bundle --no-upgrade --file="$DIR/Brewfile.extras" || echo "Some Brewfile.extras entries failed; re-run after fixing."
fi

if [ -s "$DIR/npm-globals.txt" ] && command -v npm >/dev/null; then
  echo "==> npm globals"
  while read -r pkg; do run npm install -g "$pkg"; done < "$DIR/npm-globals.txt"
fi

echo "==> dotfiles (existing files are backed up as .bak)"
cd "$DIR/dotfiles" 2>/dev/null && find . -type f | sed 's|^\./||' | while read -r f; do
  dest="$HOME/$f"
  run mkdir -p "$(dirname "$dest")"
  if [ -e "$dest" ] && ! cmp -s "$f" "$dest"; then run cp "$dest" "$dest.bak"; fi
  run cp "$f" "$dest"
done

echo "==> app settings"
if [ -d "$DIR/app-settings/files" ]; then
  (cd "$DIR/app-settings/files" && find . -type f | sed 's|^\./||' | while read -r f; do
    run mkdir -p "$(dirname "$HOME/$f")"; run cp "$f" "$HOME/$f"
  done)
fi
for p in "$DIR"/app-settings/plist/*.plist; do
  [ -f "$p" ] && run defaults import "$(basename "$p" .plist)" "$p"
done
run killall cfprefsd 2>/dev/null

echo "==> macOS defaults"
[ -f "$DIR/defaults.sh" ] && run bash "$DIR/defaults.sh"

cat <<'MSG'

Manual steps left:
  - Sign in: App Store, iCloud, your password manager, browsers, and chat/sync apps
  - Restore SSH/GPG keys, run `gh auth login`, `aws login`
  - Re-add API tokens/env secrets (never stored in this repo)
  - Grant permissions: Accessibility, Full Disk Access, Screen Recording
  - Restart to apply all macOS settings
MSG
